with target as(select * from public.works where id=any(array[1708,1715,1822,1841,1871,2020,3219,3353,3360,3427]::bigint[]) or open_library_id=any(array['OL44655382W','OL719929W','OL106870W','OL45342124W','OL733637W','OL20662980W','OL2271650W','OL921543W','OL9271127W','OL45868W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['deherinnerdesoldaat','deaansprekers','alexisofdeverhandelingoverdevergeefsestrijd','alexisouletraiteduvaincombat','dopaminekids','armance','alleenmaarnettemensen','gezichteninhetwater','facesinthewater','devruchtenvandetegenspoed','theusesofadversity','devoswasdejager','derfuchswardamalsschonderjager','mnliefjemnduifje','someonelikeyou18stories']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['deherinnerdesoldaat','deaansprekers','alexisofdeverhandelingoverdevergeefsestrijd','alexisouletraiteduvaincombat','dopaminekids','armance','alleenmaarnettemensen','gezichteninhetwater','facesinthewater','devruchtenvandetegenspoed','theusesofadversity','devoswasdejager','derfuchswardamalsschonderjager','mnliefjemnduifje','someonelikeyou18stories']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL1530219A','OL57758A','OL20371A','OL8419715A','OL2786936A','OL7127089A','OL296656A','OL81428A','OL3325335A','OL34184A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['anjetdaanje','maartenthart','martinhart','margueriteyourcenar','margueritecleenewerckdecrayencour','margueritedecrayencour','yourcenar','michaeleendoucleff','stendhal','mariehenristendhalbeyle','mariedestendhal','mariehenribeyle','robertvuijsje','janetframe','framejanet','timothygartonash','timothyashgarton','ashtimothygarton','hertamuller','roalddahl','roalddalh']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL60994031M','OL2502881M','OL25417386M','OL62207727M','OL25644070M','OL27941309M','OL61625973M','OL59621871M','OL62202292M','OL39816950M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789054523673','9789029518239','9789025315245','9789400517417','9789029546751','9789038890616','9789052261256','9789023007258','9789052261379','9789041708540']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
